-- Nomenclador de Transporte de Bienes - ARBA (Buenos Aires)
-- Fuente: https://www.arba.gov.ar/Aplicaciones/NomencladorTB/NomencladorTB.asp
-- Datos consultados el 2026-10-05. Los códigos se guardan como texto para preservar ceros iniciales.
-- Alcance: 96 capítulos publicados, códigos de rubros/productos y variedades con unidad de medida.
-- El capítulo 77 no aparece en el índice oficial consultado.
-- Esquema SQL portable (DDL ANSI + INSERT multi-row).

BEGIN TRANSACTION;

CREATE TABLE arba_nomenclador_tb (
    codigo          VARCHAR(8) NOT NULL PRIMARY KEY,
    codigo_padre    VARCHAR(8) NULL,
    nivel           SMALLINT NOT NULL,
    tipo            VARCHAR(12) NOT NULL CHECK (tipo IN ('CAPITULO', 'RUBRO', 'VARIEDAD')),
    descripcion     VARCHAR(2000) NOT NULL,
    unidad_medida   VARCHAR(80) NULL,
    CONSTRAINT fk_arba_nomenclador_padre FOREIGN KEY (codigo_padre) REFERENCES arba_nomenclador_tb(codigo)
);

-- 7.340 registros: 96 capítulos, 2.098 rubros/productos y 5.146 variedades.















CREATE INDEX ix_arba_nomenclador_padre ON arba_nomenclador_tb (codigo_padre);

COMMIT;

